// generar_282_fix_edicion_paseo_alimentacion_diaria_y_actividad_vet.js
// CHIQUI Entre Señales — Dos bugs + item de actividad en /vet
//
// 1) BUG: editar borraba la hora exacta de paseo
//    Al abrir un registro para editar, se reconstruía la opción
//    "tiempo exacto" del paseo pero NO su duración (paseoMinutos
//    quedaba en null). Como el guardado escribe la duración solo
//    cuando hay valor, si el tutor no la re-ingresaba se guardaba null
//    y la hora se perdía en silencio. Ahora la duración se restaura al
//    editar: viene cargada y solo cambia si la tocas a propósito.
//    (app/registro-diario/page.tsx)
//
// 2) BUG: la alimentación aparecía "pendiente" en Rutinas de cuidado
//    Alimentar es un cuidado DIARIO, pero se calculaba con la misma
//    lógica de "vence cada N días" que vacunas o baños. Con promedio
//    de ~1 día, cualquier redondeo o hueco la marcaba pendiente —
//    aunque ya se hubiera registrado, y aunque alimentar 1 o 2 veces
//    al día sea perfectamente normal. Ahora la alimentación es un
//    cuidado "diario": si se registró hoy dice "🟢 Al día"; si no,
//    un recordatorio suave ("¿Registraste su comida de hoy?"), nunca
//    "pendiente/atrasado", y no suma al contador de pendientes del
//    grupo. (app/analisis/page.tsx)
//
// 3) NUEVO: item de Actividad física en la vista del veterinario
//    (solo perros). Muestra el promedio diario de actividad —paseo +
//    enriquecimiento combinados, últimos 30 días— con una etiqueta
//    Activo / Moderado / Bajo. Así el vet sabe de un vistazo si es un
//    perro activo o sedentario, contexto útil para peso, conducta y
//    recomendaciones. Va junto al motivo de consulta y la dieta
//    especial, en el bloque de contexto. (app/vet/page.tsx)
//
// No hay SQL.
//
// Uso:
//   node generar_282_fix_edicion_paseo_alimentacion_diaria_y_actividad_vet.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
  {
    ruta: "app/vet/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 3 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
